async def act(page):
    """
    Locate the post titled '40 of our most helpful AI tips from 2025' and leave a comment 'Great article!'.

    Steps:
    1. Use the knowledge-base helper monitor_keyword_and_notify(...) first because it is specifically
       designed to locate articles by keyword on the homepage and the instructions require using the
       corresponding KB helper when available.
    2. If the KB helper returns a URL for the post, navigate to it. If it returns no results, fall back
       to performing a relative site search using '/?s=...'.
    3. From the search results (or KB result) locate the post link by accessibility role-based selectors.
    4. Navigate to the post page via page.goto(post_url), wait for main, find a comment textbox (role="textbox"),
       fill it with 'Great article!', then submit by clicking a submit-like button scoped under the main region
       (use parent.get_by_role('button').nth(i).click()). If no suitable button is found, press Control+Enter
       as a last resort. If clicking a button is expected to navigate away, that is the last action performed.

    Defensive practices: await locator.count() before .nth(), small try/except around fragile reads.
    """
    import urllib.parse

    query = "40 of our most helpful AI tips from 2025"

    # 1) Try the KB helper designed to scan the homepage for article headings containing the keyword.
    try:
        kb_results = await monitor_keyword_and_notify(
            page,
            query,
            check_interval_minutes=0,
            notify_via="print",
            max_results=5,
        )
    except Exception:
        kb_results = []

    post_href = None
    if kb_results:
        try:
            post_href = kb_results[0].get("url")
        except Exception:
            post_href = None

    # 2) Fallback: if KB helper didn't find the post, perform a relative site search (WordPress-style)
    if not post_href:
        search_path = f"/?s={urllib.parse.quote_plus(query)}"
        await page.goto(search_path)

        # Wait for main or networkidle
        try:
            main = page.get_by_role("main")
            if await main.count():
                await main.nth(0).wait_for(state="visible", timeout=3000)
        except Exception:
            try:
                await page.wait_for_load_state("networkidle")
            except Exception:
                pass

        # Try to find an accessible link by name (substring match)
        try:
            link_loc = page.get_by_role("link", name=query)
            if await link_loc.count():
                post_href = await link_loc.nth(0).get_attribute("href")
        except Exception:
            post_href = None

        # Additional fallback: scan all visible links for the title substring
        if not post_href:
            try:
                links = page.get_by_role("link")
                lcount = await links.count()
                for i in range(lcount):
                    l = links.nth(i)
                    try:
                        txt = (await l.inner_text() or "").strip().lower()
                    except Exception:
                        txt = ""
                    if query.lower() in txt:
                        try:
                            post_href = await l.get_attribute("href")
                        except Exception:
                            post_href = None
                        break
            except Exception:
                post_href = None

    # If we still don't have a post link, we cannot proceed
    if not post_href:
        return

    # 3) Resolve relative hrefs and navigate to the post page
    try:
        if post_href.startswith("/") or not post_href.startswith("http"):
            post_url = urllib.parse.urljoin(page.url, post_href)
        else:
            post_url = post_href
    except Exception:
        post_url = post_href

    # Navigate to the post (this navigation is performed before interacting with the comment UI)
    await page.goto(post_url)

    # Wait for main content if present
    try:
        main = page.get_by_role("main")
        if await main.count():
            await main.nth(0).wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # Scope further selectors inside main when available
    try:
        parent = page.get_by_role("main")
        if await parent.count():
            parent = parent.nth(0)
        else:
            parent = page
    except Exception:
        parent = page

    # 4) Locate a role="textbox" for comment input
    try:
        textbox_locator = parent.get_by_role("textbox")
        tb_count = await textbox_locator.count()
    except Exception:
        textbox_locator = page.get_by_role("textbox")
        try:
            tb_count = await textbox_locator.count()
        except Exception:
            tb_count = 0

    if tb_count == 0:
        # No accessible textbox found; cannot leave a comment reliably
        return

    # Prefer a textbox whose aria-label or placeholder indicates a comment
    target_tb = None
    for i in range(tb_count):
        tb = textbox_locator.nth(i)
        try:
            aria = (await tb.get_attribute("aria-label") or "").lower()
        except Exception:
            aria = ""
        try:
            placeholder = (await tb.get_attribute("placeholder") or "").lower()
        except Exception:
            placeholder = ""
        if any(k in aria for k in ["comment", "your comment", "leave a reply"]) or any(k in placeholder for k in ["comment", "your comment", "leave a reply"]) or tb_count == 1:
            target_tb = tb
            break

    if not target_tb:
        target_tb = textbox_locator.nth(0)

    # Fill the comment
    try:
        await target_tb.fill("Great article!")
    except Exception:
        return

    # 5) Attempt to submit: prefer buttons scoped under the same parent region
    submitted = False
    try:
        buttons = parent.get_by_role("button")
        bcount = await buttons.count()
    except Exception:
        buttons = page.get_by_role("button")
        try:
            bcount = await buttons.count()
        except Exception:
            bcount = 0

    if bcount:
        for i in range(bcount):
            try:
                candidate = parent.get_by_role("button").nth(i)
                txt = (await candidate.inner_text() or "").strip().lower()
            except Exception:
                txt = ""
            if any(k in txt for k in ["post comment", "post", "submit", "send", "add comment", "leave a reply", "comment"]):
                try:
                    # Clicking the submit-like button is the final action (it may navigate away)
                    await parent.get_by_role("button").nth(i).click()
                    submitted = True
                    return
                except Exception:
                    continue

    # Last-resort: press Control+Enter inside the textbox (does not require additional selectors)
    try:
        await target_tb.press("Control+Enter")
    except Exception:
        pass

    return

